/**
 * A synthetic web corpus.
 *
 * The course never downloads a corpus. Instead it builds one: a population of
 * documents, each with a latent topic, a measurable amount of signal, a
 * provenance (which domain it came from) and a duplication relationship to
 * another document. The point is that every property the filters will act on is
 * *known*, so the effect of a filter can be measured against the truth rather
 * than merely displayed.
 *
 * The text is generated by a **Markov chain**, not by sampling tokens
 * independently, because the filters are n-gram filters. Independent sampling
 * would make ordinary text look like noise to any language model; a chain
 * gives the corpus genuine local structure, so that "this document is unlike
 * the reference distribution" is a statement with a meaning.
 *
 * Three kinds of junk are mixed in, and each is caught by a different filter:
 *
 * - **Boilerplate**: a short phrase, repeated, unique to the document. Its
 *   words are common, so a *unigram* model rates it as good text; its
 *   n-gram context is wrong, so an n-gram model rates it as junk.
 * - **Foreign text**: tokens drawn from a disjoint part of the vocabulary,
 *   which no reference model fit on the rest of the corpus can predict.
 * - **Near-duplicates**: copies of other documents with a few tokens changed.
 */

import { createRng, type Rng } from '@llm-materials/course-core'

export const DOMAINS = ['books', 'news', 'code', 'forum', 'reference'] as const
export type Domain = (typeof DOMAINS)[number]

export const DOMAIN_INDEX: Record<Domain, number> = {
  books: 0,
  news: 1,
  code: 2,
  forum: 3,
  reference: 4,
}

export interface Document {
  id: number
  /** The token identifiers of the document. */
  tokens: number[]
  /** The domain the document came from. */
  domain: Domain
  /** The latent topic the document is about. */
  topic: number
  /** The fraction of the document's tokens that carry signal. */
  quality: number
  /** The document this one is a near-duplicate of, if any. */
  duplicateOf: number | null
  /** Whether the document is boilerplate. */
  isSpam: boolean
  /** Whether the document is in a language the reference model has never seen. */
  isForeign: boolean
}

export interface CorpusOptions {
  /** How many documents to generate. */
  size?: number
  /** The size of the vocabulary. */
  vocabulary?: number
  /** How many topics there are. */
  topics?: number
  /** The average document length, in tokens. */
  length?: number
  /** The probability that a document is a near-duplicate of an earlier one. */
  duplicateRate?: number
  /** The probability that a document is boilerplate. */
  spamRate?: number
  /** The probability that a document is in an unseen language. */
  foreignRate?: number
  /** The seed. */
  seed?: number
}

export interface Corpus {
  documents: Document[]
  vocabulary: number
  topics: number
  /** The background distribution over the vocabulary. */
  background: number[]
  /** The topic distributions over the vocabulary, one per topic. */
  topicDistributions: number[][]
  options: Required<CorpusOptions>
}

/**
 * Build the corpus.
 *
 * The signal is not free: a document's quality is drawn first, and the tokens
 * are then drawn to *match* that quality, so the ground truth and the
 * observable text agree. That is what makes the ablations meaningful.
 */
export function buildCorpus(options: CorpusOptions = {}): Corpus {
  const settings: Required<CorpusOptions> = {
    size: 600,
    vocabulary: 48,
    topics: 5,
    length: 80,
    duplicateRate: 0.18,
    spamRate: 0.08,
    foreignRate: 0.06,
    seed: 17,
  }
  Object.assign(settings, options)

  const rng = createRng(settings.seed)
  const { vocabulary, topics } = settings
  // The foreign range is the top third of the vocabulary, which the ordinary
  // documents never use.
  const foreignStart = Math.floor(vocabulary * 0.7)

  // The background distribution: a Zipf-like profile, so that some tokens are
  // common and most are rare.
  const background: number[] = []
  for (let i = 0; i < vocabulary; i++) {
    background.push(1 / (i + 1) ** 1.1)
  }
  const backgroundTotal = background.reduce((a, b) => a + b, 0)
  for (let i = 0; i < vocabulary; i++) background[i] = (background[i] ?? 0) / backgroundTotal

  // The transition matrix of the background chain. Each token has a couple of
  // *preferred* successors, and the preferred ones are markedly more likely
  // than the rest. That is what gives the corpus pair structure: some bigrams
  // are common and most are not, so an n-gram model can tell a phrase that
  // fits the corpus from one that does not.
  const preferred: number[][] = []
  for (let i = 0; i < vocabulary; i++) {
    const successors = new Set<number>()
    while (successors.size < 2) {
      const candidate = Math.floor(rng() * foreignStart)
      if (candidate !== i) successors.add(candidate)
    }
    preferred.push([...successors])
  }

  const transitions: number[][] = []
  for (let i = 0; i < vocabulary; i++) {
    const row = background.map((p, j) =>
      j < foreignStart ? p * (preferred[i]!.includes(j) ? 6 : 1) : 0,
    )
    const total = row.reduce((a, b) => a + b, 0)
    transitions.push(row.map((value) => value / total))
  }

  // Each topic has an anchor token and a marker token. The pair is what makes
  // the topic visible to the classifier, and it is a *preferred* bigram of the
  // anchor, so that the topic's own n-grams are not penalised by the
  // reference model.
  const anchors: number[] = []
  const markers: number[] = []
  for (let t = 0; t < topics; t++) {
    const anchor = t % foreignStart
    anchors.push(anchor)
    const marker = (t + 7) % foreignStart
    markers.push(marker)
    if (!preferred[anchor]!.includes(marker)) preferred[anchor]!.push(marker)
  }

  // Rebuild the transitions now that the topic markers have been added.
  for (let i = 0; i < vocabulary; i++) {
    const row = background.map((p, j) =>
      j < foreignStart ? p * (preferred[i]!.includes(j) ? 6 : 1) : 0,
    )
    const total = row.reduce((a, b) => a + b, 0)
    transitions[i] = row.map((value) => value / total)
  }

  // The topic distributions over the vocabulary, for the alignment filter.
  const topicDistributions: number[][] = []
  for (let t = 0; t < topics; t++) {
    const distribution = background.map((p) => p * 0.3)
    distribution[anchors[t]!] = (distribution[anchors[t]!] ?? 0) + 0.4
    distribution[markers[t]!] = (distribution[markers[t]!] ?? 0) + 0.2
    const total = distribution.reduce((a, b) => a + b, 0)
    for (let i = 0; i < vocabulary; i++) distribution[i] = (distribution[i] ?? 0) / total
    topicDistributions.push(distribution)
  }

  const documents: Document[] = []
  for (let id = 0; id < settings.size; id++) {
    const domain = DOMAINS[id % DOMAINS.length] as Domain
    const topic = Math.floor(rng() * topics)
    const isSpam = rng() < settings.spamRate
    const isForeign = !isSpam && rng() < settings.foreignRate
    const length = Math.max(8, Math.round(settings.length * (0.5 + rng())))
    const quality = isSpam ? 0.02 : isForeign ? 0.05 : Math.min(0.98, 0.15 + 0.8 * rng() ** 1.4)

    let tokens: number[]
    if (isSpam) {
      // Boilerplate: a phrase of the commonest words, arranged in an order
      // the corpus never uses, repeated. A *unigram* model rates it as good
      // text; an n-gram model does not, because the arrangement is wrong.
      const phraseLength = 3 + Math.floor(rng() * 3)
      const phrase: number[] = []
      for (let t = 0; t < phraseLength; t++) {
        // Only the commonest words, so that the unigram model is happy.
        phrase.push(Math.floor(rng() ** 2 * 6))
      }
      tokens = []
      for (let t = 0; t < length; t++) tokens.push(phrase[t % phrase.length] ?? 0)
    } else if (isForeign) {
      // A language the reference model has never seen: its tokens live in the
      // part of the vocabulary the ordinary documents never use.
      tokens = []
      for (let t = 0; t < length; t++) {
        tokens.push(foreignStart + Math.floor(rng() * (vocabulary - foreignStart)))
      }
    } else {
      // An ordinary document: a walk along the background chain, with the
      // topic's marker pair inserted at the rate the quality says.
      tokens = []
      let state = Math.floor(rng() * foreignStart)
      let previous = -1
      for (let t = 0; t < length; t++) {
        if (previous >= 0 && rng() < quality) {
          tokens.push(anchors[topic]!)
          tokens.push(markers[topic]!)
          previous = markers[topic]!
          state = previous
          continue
        }
        const next = sampleFrom(transitions[state]!, rng)
        tokens.push(next)
        previous = next
        state = next
      }
    }

    documents.push({
      id,
      tokens,
      domain,
      topic,
      quality,
      duplicateOf: null,
      isSpam,
      isForeign,
    })
  }

  // Near-duplicates: a copy of an earlier document with a few tokens changed.
  for (let id = 0; id < documents.length; id++) {
    const document = documents[id]!
    if (document.isSpam || document.isForeign) continue
    if (rng() >= settings.duplicateRate) continue
    const source = documents[Math.floor(rng() * id)]!
    if (source.isSpam || source.isForeign) continue
    const mutationRate = 0.02 + 0.06 * rng()
    const tokens = source.tokens.map((token) => (rng() < mutationRate ? Math.floor(rng() * foreignStart) : token))
    document.duplicateOf = source.id
    document.tokens = tokens
    document.quality = source.quality * (1 - mutationRate)
    document.topic = source.topic
    document.domain = source.domain
  }

  return { documents, vocabulary, topics, background, topicDistributions, options: settings }
}

/** Draw one token from a distribution. */
function sampleFrom(distribution: number[], rng: Rng): number {
  const u = rng()
  let cumulative = 0
  for (let i = 0; i < distribution.length; i++) {
    cumulative += distribution[i] ?? 0
    if (u <= cumulative) return i
  }
  return distribution.length - 1
}

/** The number of tokens in a document. */
export function tokenCount(document: Document): number {
  return document.tokens.length
}

/**
 * The bag-of-tokens count vector of a document.
 *
 * This is the representation the course's models read. It is deliberately
 * simple: the point is the data pipeline, not the architecture.
 */
export function bagOfTokens(document: Document, vocabulary: number): number[] {
  const counts = new Array<number>(vocabulary).fill(0)
  for (const token of document.tokens) counts[token] = (counts[token] ?? 0) + 1
  return counts
}

/**
 * The bag-of-tokens count vector, scaled to unit length.
 *
 * The scaling matters: without it a long document dominates the gradient of
 * the classifier, and the learning rate that works for a short document makes
 * a long one diverge.
 */
export function normalisedBag(document: Document, vocabulary: number): number[] {
  const counts = bagOfTokens(document, vocabulary)
  const norm = Math.sqrt(counts.reduce((sum, value) => sum + value * value, 0))
  if (norm === 0) return counts
  return counts.map((value) => value / norm)
}

/** The mean quality of a set of documents. */
export function meanQuality(documents: Document[]): number {
  if (documents.length === 0) return 0
  const total = documents.reduce((sum, document) => sum + document.quality, 0)
  return total / documents.length
}

/** The fraction of a set of documents that are near-duplicates. */
export function duplicateFraction(documents: Document[]): number {
  if (documents.length === 0) return 0
  const duplicates = documents.filter((document) => document.duplicateOf !== null).length
  return duplicates / documents.length
}

/** The number of documents from each domain. */
export function domainCounts(documents: Document[]): number[] {
  const counts = new Array<number>(DOMAINS.length).fill(0)
  for (const document of documents) {
    counts[DOMAIN_INDEX[document.domain]] = (counts[DOMAIN_INDEX[document.domain]] ?? 0) + 1
  }
  return counts
}
